  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']

    # Build maps
    node_info = {}
    children = {}
    for n in nodes:
        nid = n['id']
        node_info[nid] = n
        children[nid] = []
    for n in nodes:
        pid = n.get('parent')
        if pid is not None:
            children[pid].append(n['id'])

    # Validate required symbols exist
    symbol_set = set(n['symbol'] for n in nodes)
    for sym in required_symbols:
        if sym not in symbol_set:
            raise ValueError(f"Required symbol '{sym}' not present in tree")

    # Root identification
    root_id = None
    for nid, info in node_info.items():
        if info.get('parent') is None:
            root_id = nid
            break
    if root_id is None:
        raise ValueError("Tree has no root")

    # Sort nodes: depth descending, then ID ascending (lexicographic)
    all_ids = list(node_info.keys())
    all_ids.sort(key=lambda nid: (-node_info[nid]['depth'], nid))

    retained = set(all_ids)
    removed_order = []

    # Memo for subtree (cache per node, since state changes we compute fresh)
    def get_retained_subtree(node_id):
        """Return set of node_ids in subtree (node included) that are still retained."""
        stack = [node_id]
        subtree = set()
        while stack:
            cur = stack.pop()
            if cur in retained:
                subtree.add(cur)
                for child in children[cur]:
                    if child in retained:
                        stack.append(child)
        return subtree

    for nid in all_ids:
        if nid not in retained:
            continue
        info = node_info[nid]
        # Skip root
        if nid == root_id:
            continue
        # Skip if symbol is required
        if info['symbol'] in required_symbols:
            continue
        # Skip if node is not removable
        if not info['removable']:
            continue
        # Check for any retained immediate children
        has_retained_children = any(child in retained for child in children[nid])
        if has_retained_children:
            continue

        # Compute the subtree that would be removed (only retained nodes)
        to_remove = get_retained_subtree(nid)
        if not to_remove:
            continue

        # Temporarily remove to check required symbols
        remaining = retained - to_remove
        required_ok = True
        for sym in required_symbols:
            # Check if any node with that symbol remains
            present = any(node_info[rid]['symbol'] == sym for rid in remaining)
            if not present:
                required_ok = False
                break
        if required_ok:
            removed_order.append(nid)
            retained = remaining

    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }"
}
